(function(root){
  'use strict';
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let admin=false,checking=false,retryRequested=false;
  function isAdmin(){return admin;}
  async function client(){if(!window.YamaAccountUI?.isSignedIn())throw new Error('Přihlas se účtem vlastníka Yamaportalu.');return window.YamaPortalIntegration.sharedClient(location.origin);}
  async function verify(){const sb=await client();const {data:userData,error:userError}=await sb.auth.getUser();if(userError||!userData?.user)throw new Error('Přihlášení už není platné. Přihlas se znovu.');const {data,error}=await sb.rpc('platform_admin_status');if(error)throw new Error('Ověření oprávnění se nepodařilo. Zkus to později.');if(data!==true)throw new Error('Tento účet nemá oprávnění správce Portalu.');return {sb,user:userData.user};}
  async function init(){if(checking){retryRequested=true;return;}checking=true;const previous=admin;try{await verify();admin=true;}catch{admin=false;}finally{checking=false;if(previous!==admin){window.dispatchEvent(new Event('yama-admin-state'));}if(retryRequested){retryRequested=false;void init();}}}
  function markup(){return '<section class="panel page-content owner-admin"><p class="eyebrow">VLASTNICKÁ SPRÁVA</p><h2>Správa Yamaportalu</h2><p class="muted">Oprávnění ověřuje zabezpečený účet Yamachat. Tato stránka neposkytuje administraci podle e-mailu ani údajů uložených v prohlížeči.</p><div class="admin-state" role="status">Ověřuji roli vlastníka…</div><div class="admin-content" hidden><div class="admin-stats"><article class="admin-stat"><span>Účty Yamachat</span><strong data-admin-user-count>—</strong><small>profilů dostupných správci</small></article><article class="admin-stat"><span>Oprávnění</span><strong>Vlastník</strong><small>ověřeno serverem</small></article></div><section class="admin-section"><h3>Uživatelské profily</h3><p class="caption">Z bezpečnostních důvodů se zde zobrazují jen veřejné údaje profilu. E-maily ani přihlašovací údaje se nenačítají.</p><div class="admin-users" data-admin-users><p>Načítám…</p></div></section><section class="admin-section"><h3>Oznámení uživatelům</h3><p class="caption">Oznámení se uloží do schránky každého profilu Yamachat. Odeslání je skutečné a spustí se až po tvém výslovném potvrzení.</p><form data-admin-broadcast><label for="admin-title">Nadpis</label><input id="admin-title" name="title" maxlength="120" required><label for="admin-body">Zpráva</label><textarea id="admin-body" name="body" rows="5" maxlength="4000" required></textarea><label for="admin-kind">Typ oznámení</label><select id="admin-kind" name="kind"><option value="info">Informace</option><option value="important">Důležité</option><option value="warning">Upozornění</option></select><label class="admin-confirm"><input type="checkbox" name="confirm" required>Rozumím, že tato zpráva bude odeslána všem uživatelům Yamachat.</label><button class="primary" type="submit">Odeslat všem uživatelům</button><p class="form-status" data-admin-status role="status"></p></form></section><section class="admin-section"><h3>Moderace a hlášení</h3><p class="caption">Yamachat už má ověřené nástroje pro prohlížení uživatelů, odeslání individuální zprávy, zablokování účtu a práci s hlášeními. Zachovávají vlastní serverové kontroly oprávnění.</p><a class="secondary" href="#yamachat">Otevřít Yamachat a jeho stávající správu →</a></section><p class="caption">Správa komunit a zpětné vazby zůstává v administračním rozhraní Yamachatu.</p></div></section>';}
  async function load(){const state=document.querySelector('.admin-state'),content=document.querySelector('.admin-content');if(!state||!content)return;state.hidden=false;content.hidden=true;state.textContent='Ověřuji roli vlastníka…';try{const {sb}=await verify();admin=true;const {data:profiles,error}=await sb.from('profiles').select('id,username,display_name,created_at').order('created_at',{ascending:false}).limit(100);if(error)throw new Error('Seznam uživatelů se nepodařilo načíst.');const rows=profiles||[];content.querySelector('[data-admin-user-count]').textContent=String(rows.length);content.querySelector('[data-admin-users]').innerHTML=rows.length?'<ul>'+rows.map(p=>'<li><strong>'+esc(p.display_name||p.username||'Uživatel')+'</strong><span>@'+esc(p.username||'')+'</span><small>Účet od '+esc(new Intl.DateTimeFormat('cs-CZ',{dateStyle:'medium'}).format(new Date(p.created_at)))+'</small></li>').join('')+'</ul>':'<p>Zatím nejsou dostupné žádné profily.</p>';state.hidden=true;content.hidden=false;}catch(error){admin=false;state.textContent=error.message||'Správu se nepodařilo načíst.';}}
  document.addEventListener('submit',async event=>{const form=event.target.closest('[data-admin-broadcast]');if(!form)return;event.preventDefault();const button=form.querySelector('[type=submit]'),status=form.querySelector('[data-admin-status]'),values=new FormData(form);button.disabled=true;status.textContent='Ověřuji oprávnění a připravuji doručení…';try{const {sb,user}=await verify();const {data:profiles,error}=await sb.from('profiles').select('id').limit(1001);if(error)throw new Error('Seznam příjemců se nepodařilo ověřit. Zpráva nebyla odeslána.');if((profiles||[]).length>1000)throw new Error('Počet účtů překročil bezpečný limit 1 000. Zpráva nebyla odeslána.');const recipients=(profiles||[]).map(p=>p.id);if(!recipients.length)throw new Error('Nebyly nalezeny žádné účty. Zpráva nebyla odeslána.');const message={title:String(values.get('title')||'').trim(),body:String(values.get('body')||'').trim(),kind:String(values.get('kind')||'info'),created_by:user.id};if(!message.title||!message.body)throw new Error('Vyplň nadpis i zprávu.');const batch=recipients.map(recipient_user_id=>({...message,recipient_user_id}));const {error:sendError}=await sb.from('account_messages').insert(batch);if(sendError)throw new Error('Odeslání se nepodařilo. Server neuložil potvrzení o doručení.');status.textContent='Zpráva byla uložena do schránky '+recipients.length+' uživatelů.';form.reset();}catch(error){status.textContent=error.message||'Zpráva nebyla odeslána.';}finally{button.disabled=false;}});
  window.YamaAdminUI=Object.freeze({isAdmin,init,markup,load});
})(window);
